import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { AuthResponse } from '@/types';
import { Investment, Transaction } from '@/types/InvestmentType';
import { apiRequest } from './request';

export type InvestPayload = seed.InvestPayload;

export async function invest(payload: InvestPayload): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.invest(payload);

  return apiRequest<AuthResponse>(URLS.INVESTMENTS, {
    method: 'POST',
    body: payload,
  });
}

export async function getInvestments(): Promise<Investment[]> {
  if (USE_SEED_DATA) return seed.getInvestments();

  const json = await apiRequest<{ result: Investment[] }>(URLS.INVESTMENTS);
  return json.result;
}

export async function getTransactions(): Promise<Transaction[]> {
  if (USE_SEED_DATA) return seed.getTransactions();

  const json = await apiRequest<{ result: Transaction[] }>(URLS.TRANSACTIONS);
  return json.result;
}

export async function toggleFavorite(houseId: string): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.toggleFavorite(houseId);

  return apiRequest<AuthResponse>(URLS.FAVORITES, {
    method: 'POST',
    body: { houseId },
  });
}
